'use strict';

const prices = [599, 999, 1999, 2999, 4999, 9999, 19999, 29999, 49999];
const small = 'resources/shop/shop_premium_pack_small.png';
const medium = 'resources/shop/shop_premium_pack_medium.png';
const large = 'resources/shop/shop_premium_pack_large.png';
const massive = 'resources/shop/shop_premium_pack_massive.png';
const ultimate = 'resources/shop/shop_premium_pack_ultimate.png';
const packArt = [small, small, medium, medium, large, large, massive, massive, ultimate];

const products = prices.map((amountCents, index) => ({
  sku: `usd-${amountCents}`,
  currency: 'USD',
  amountCents,
  diamonds: Math.floor(amountCents / 10),
  image: packArt[index],
}));

function readReservation(input) {
  if (!input || typeof input.requestId !== 'string' || !/^[0-9a-f]{32}$/.test(input.requestId)) {
    return null;
  }
  const product = products.find(({ sku }) => sku === input.sku);
  if (!product || input.amountCents !== product.amountCents || input.currency !== product.currency) {
    return null;
  }
  return { requestId: input.requestId, product };
}

module.exports = { products, readReservation };

